<?php use ImWiki\Security\Csrf;use ImWiki\Security\Html;use ImWiki\Support\Url;$isEdit=(bool)$edited;$title=$isEdit?'Edytuj użytkownika':'Dodaj użytkownika';$selected=$edited['role_ids']??[];?>
<div class="page-head"><div><p class="eyebrow">Administracja · Użytkownicy</p><h1><?=Html::e($title)?></h1></div><a class="button secondary" href="<?=Html::e(Url::to('/admin/users'))?>">Wróć</a></div>
<?php if($error):?><div class="alert danger"><?=Html::e($error)?></div><?php endif;?><?php if(isset($_GET['saved'])):?><div class="alert success">Zmiany zapisano.</div><?php endif;?><?php if(isset($_GET['password'])):?><div class="alert success">Hasło zresetowano. Pozostałe sesje użytkownika zostały unieważnione.</div><?php endif;?>
<section class="card section-card"><form method="post" class="grid compact-form" action="<?=Html::e($isEdit?Url::to('/admin/users/'.$edited['id'].'/edit'):Url::to('/admin/users/create'))?>"><?=Csrf::field()?><label>Login<input name="username" pattern="[A-Za-z0-9._-]{3,100}" value="<?=Html::e($edited['username']??'')?>" required></label><label>E-mail<input name="email" type="email" maxlength="190" value="<?=Html::e($edited['email']??'')?>" required></label><label>Imię<input name="first_name" maxlength="100" value="<?=Html::e($edited['first_name']??'')?>"></label><label>Nazwisko<input name="last_name" maxlength="100" value="<?=Html::e($edited['last_name']??'')?>"></label><?php if(!$isEdit):?><label>Hasło<input name="password" type="password" minlength="10" required autocomplete="new-password"></label><?php else:?><label>Status<select name="status"><?php foreach(['active'=>'Aktywne','blocked'=>'Zablokowane','disabled'=>'Wyłączone'] as $v=>$l):?><option value="<?=$v?>" <?=($edited['status']??'')===$v?'selected':''?>><?=$l?></option><?php endforeach;?></select></label><?php endif;?><fieldset><legend>Role</legend><?php foreach($roles as $role):?><label class="check-row"><input type="checkbox" name="roles[]" value="<?=Html::e($role['id'])?>" <?=in_array((int)$role['id'],$selected,true)?'checked':''?>> <?=Html::e($role['label'])?> <small><?=Html::e($role['name'])?></small></label><?php endforeach;?></fieldset><label class="check-row"><input type="checkbox" name="force_password_change" value="1" <?=!empty($edited['force_password_change'])?'checked':''?>> Wymuś zmianę hasła przy następnym logowaniu</label><div class="form-action"><button class="button">Zapisz</button></div></form></section>
<?php if($isEdit):?><section class="card section-card"><h2>Reset hasła</h2><form method="post" action="<?=Html::e(Url::to('/admin/users/'.$edited['id'].'/password'))?>" class="inline-review-form"><?=Csrf::field()?><label>Nowe hasło<input name="password" type="password" minlength="10" required autocomplete="new-password"></label><button class="button secondary">Ustaw hasło i wyloguj sesje</button></form></section><section class="card section-card danger-zone"><h2>Usuń użytkownika</h2><p class="muted">Konto zostanie soft-delete, a aktywne sesje zostaną unieważnione. Audit pozostaje zachowany.</p><form method="post" action="<?=Html::e(Url::to('/admin/users/'.$edited['id'].'/delete'))?>" onsubmit="return confirm('Usunąć użytkownika?')"><?=Csrf::field()?><button class="button danger">Usuń użytkownika</button></form></section><?php endif;?>
